/**
 * # Press detail payload
 *
 * Builds everything `/press/<slug>` renders, in one place.
 *
 * Previously each site's `pages/press/[...slug].astro` frontmatter
 * carried a byte-identical 165-line copy of this orchestration
 * (related-entry expansion, author resolution, publication org links,
 * award reverse-lookup, featured propagation). This hoist follows the
 * same dependency-injection shape already used by
 * `preparePressIndexSections` and `createFeaturedPropagation`: site-core
 * can't import `astro:content`, so the caller passes in a `loadEntry`
 * function plus the already-loaded, already-draft-filtered collections.
 *
 * ## Detail-route eligibility
 *
 * `isPressDetailRouted` is the single rule deciding which press entries
 * get a `/press/<id>` page. It is exported so `getStaticPaths` and any
 * link-building code answer the question identically — an external
 * story must never be linked to a page that was never generated.
 */
import { findAwardsForEntity } from "./award-helpers.js";
import { expandEntries } from "./entry-loader.js";
import { toOrganizationCardData } from "./card-mapper-helpers.js";
import { withResolvedLinks, withoutSelfLinks, } from "./content-links.js";
import { resolvePersonHeadline } from "./person-view-models.js";
/**
 * Roles an organization can hold on a publication.
 *
 * Canonical runtime list for site-core and its consumers.
 * `ecosystem-content-schema` declares the matching `z.enum` on
 * `publicationOrganizationSchema` — site-core intentionally does not
 * depend on the schema package, so the two declarations must be kept in
 * step by hand. Both are named exports specifically so a drift is
 * greppable rather than buried in an inline literal.
 */
export const PUBLICATION_ORGANIZATION_ROLES = [
    "lead",
    "affiliated",
    "funding",
    "collaborator",
];
const PUBLICATION_ORGANIZATION_ROLE_SET = new Set(PUBLICATION_ORGANIZATION_ROLES);
/** True when `role` is a recognized publication-organization role. */
export function isPublicationOrganizationRole(role) {
    return typeof role === "string" && PUBLICATION_ORGANIZATION_ROLE_SET.has(role);
}
export function isPressDetailRouted(data) {
    if (data.type === "story")
        return !data.externalUrl;
    return true;
}
/**
 * Build the full render payload for one press entry.
 *
 * Every related collection is passed through `featured.resolveAll` —
 * propagated, then given a resolved `featured` flag — so an item that
 * is featured-by-propagation (for example, because it won
 * an award) renders with its featured badge everywhere it appears —
 * including in `relatedPress`, which earlier hand-written copies of this
 * logic passed through raw.
 */
export async function preparePressDetail(args) {
    const { entry, loadEntry, featured, allAwards, orgDisplayLookup, homeOrgId } = args;
    // A press item can itself be an award recipient (e.g. "Best Paper"),
    // so apply propagation before reading `data`.
    const resolved = featured.resolve(entry, "press");
    const data = resolved.data;
    // `PublicationDetail` renders a narrower set than `PressDetail` — it has
    // no props for events, people, or organizations — so those are only
    // resolved for the variants that can actually show them.
    const isPublication = data.type === "publication";
    const [relatedHardware, relatedSoftware, relatedResearch, relatedEvents, relatedPeople, relatedOrganizations, relatedPress,] = await Promise.all([
        expandEntries(loadEntry, "hardware", data.relatedHardware),
        expandEntries(loadEntry, "software", data.relatedSoftware),
        expandEntries(loadEntry, "research", data.relatedResearch),
        isPublication ? [] : expandEntries(loadEntry, "events", data.relatedEvents),
        isPublication ? [] : expandEntries(loadEntry, "people", data.relatedPeople),
        isPublication
            ? []
            : expandEntries(loadEntry, "organizations", data.relatedOrganizations),
        expandEntries(loadEntry, "press", data.relatedPress),
    ]);
    // Authors. For publications, prefer the contributor's explicit
    // `order`/`corresponding`/`equalContribution`/`affiliationSnapshot`
    // fields when set. Announcements and stories fall back to array-index
    // ordering with no special-author markers.
    const contributors = Array.isArray(data.contributors)
        ? data.contributors
        : [];
    const resolvedAuthors = (await Promise.all(contributors.map(async (c, i) => {
        if (c.type !== "person" || typeof c.personId !== "string")
            return null;
        const person = await loadEntry("people", c.personId);
        let affiliationSnapshot = typeof c.affiliationSnapshot === "string"
            ? c.affiliationSnapshot
            : undefined;
        const personData = person?.data;
        if (!affiliationSnapshot && personData?.affiliations?.length) {
            affiliationSnapshot = resolvePersonHeadline(personData, {
                homeOrgId,
                orgDisplayLookup,
            }).label;
        }
        return {
            personId: c.personId,
            order: typeof c.order === "number" ? c.order : i + 1,
            corresponding: c.corresponding === true,
            equalContribution: c.equalContribution === true,
            affiliationSnapshot,
            person: person?.data ?? null,
        };
    }))).filter((a) => a !== null);
    // Publication-only resolutions: parent research programs and
    // research-style organization links.
    let fromResearch = [];
    const organizationLinks = [];
    if (isPublication) {
        fromResearch = await expandEntries(loadEntry, "research", data.fromResearch);
        const links = Array.isArray(data.organizations)
            ? data.organizations
            : [];
        for (const link of links) {
            if (!isPublicationOrganizationRole(link.role))
                continue;
            if (typeof link.organizationId !== "string")
                continue;
            const org = await loadEntry("organizations", link.organizationId);
            if (!org)
                continue;
            organizationLinks.push({
                role: link.role,
                note: typeof link.note === "string" ? link.note : undefined,
                organization: {
                    ...toOrganizationCardData(org.data),
                    id: org.id,
                },
            });
        }
    }
    return {
        data: withResolvedLinks(withoutSelfLinks(data, "press", entry.id, featured.site), featured.site.basePath),
        shouldRenderBody: data.renderMarkdown === true,
        authors: resolvedAuthors,
        organizationLinks,
        fromResearch: featured.resolveAll(fromResearch, "research"),
        relatedHardware: featured.resolveAll(relatedHardware, "hardware"),
        relatedSoftware: featured.resolveAll(relatedSoftware, "software"),
        relatedResearch: featured.resolveAll(relatedResearch, "research"),
        relatedEvents: featured.resolveAll(relatedEvents, "events"),
        relatedPeople: featured.resolveAll(relatedPeople, "people"),
        relatedOrganizations: featured.resolveAll(relatedOrganizations, "organizations"),
        relatedPress: featured.resolveAll(relatedPress, "press"),
        awards: findAwardsForEntity(allAwards, "press", entry.id),
        isPublication,
    };
}
