/**
 * # Site context
 *
 * Everything a shared builder needs to know about *which* build it is
 * part of: the site key, the origin it deploys to, the base path it is
 * served under, and the instant the build treats as "now".
 *
 * Three sites build from one content hub, so most of what this package
 * computes is only correct relative to a site: an entry is featured
 * *here*, a link is a self-link *on this origin*, a path resolves
 * *under this base*. Read from separate defaults — a module variable per
 * value, an env var, a fresh `new Date()` per call — those answers can
 * disagree within one page, and a missing site key has no safe default.
 * A context is built once, validated once, and passed where it is
 * needed.
 *
 * ## How it reaches shared code
 *
 * - **Builders** (`createFeaturedPropagation`, `buildProjectsPayload`,
 *   `preparePressIndexSections`, the detail payload builders) accept a
 *   `site` argument, or get one from the propagation handle, which
 *   carries the context it was built with.
 * - **Rendered components** read featured state that a builder has
 *   already resolved into the view model (`data.featured`), so a
 *   hydrated island never has to know the site or the clock.
 *
 * ## The ambient fallback
 *
 * Card converters and detail views run inside shared components that
 * take no site argument. When the view model carries no resolved flag,
 * they fall back to the context installed with `setActiveSiteContext`
 * (or the compatibility setter `setActiveSiteKey`). That fallback exists so server
 * rendering keeps working while call sites move to resolved view
 * models. When nothing is installed, featured-state resolution throws
 * `MissingSiteContextError` rather than guessing. The only available
 * guess, "featured on any site", is wrong on every site but the one
 * that featured the entry, and it looks exactly like a correct answer.
 */
/**
 * Thrown when featured state is resolved with no site to resolve it
 * for. It names the caller so the stack points at the entry point that
 * forgot to establish a context, not at the primitive that noticed.
 */
export class MissingSiteContextError extends Error {
    constructor(caller) {
        super(`${caller} needs a site to resolve featured state for, and none was ` +
            `given. Pass a site key or a SiteContext, or resolve \`featured\` ` +
            `into the view model at build time. There is deliberately no ` +
            `"featured on any site" default; for that question, call ` +
            `\`isFeatured\` with no site key.`);
        this.name = "MissingSiteContextError";
    }
}
/**
 * Normalize an origin-bearing url to bare `scheme://host[:port]`.
 * Returns `undefined` for an unparseable value.
 */
export function normalizeOrigin(value) {
    if (!value)
        return undefined;
    try {
        return new URL(value).origin;
    }
    catch {
        return undefined;
    }
}
/**
 * Build a validated, frozen site context. Construction is where
 * configuration mistakes surface: an empty site key or an unparseable
 * origin throws here, once, instead of degrading every later check.
 */
export function createSiteContext(init) {
    if (typeof init.siteKey !== "string" || init.siteKey.length === 0) {
        throw new TypeError("createSiteContext: `siteKey` must be a non-empty string");
    }
    const origin = normalizeOrigin(init.origin);
    if (init.origin && !origin) {
        throw new TypeError(`createSiteContext: \`origin\` is not an absolute url: ${init.origin}`);
    }
    // Copied, so a caller mutating its own Date afterwards cannot move
    // this build's clock.
    const now = new Date((init.now ?? new Date()).getTime());
    if (Number.isNaN(now.getTime())) {
        throw new TypeError("createSiteContext: `now` is an invalid Date");
    }
    return Object.freeze({
        siteKey: init.siteKey,
        origin,
        basePath: init.basePath || undefined,
        now,
    });
}
let activeContext;
/**
 * Install the context that shared components fall back to when a view
 * model carries no resolved featured state. Call once, where the
 * site's configuration is evaluated.
 *
 * This is a bridge for server rendering, not the primary way context
 * flows: builders take `site` explicitly, and islands receive resolved
 * values as props. In the browser, whether the installing module has
 * run depends on which chunks happen to have loaded, and when it has,
 * the clock it captured is the visitor's — which is why nothing rendered
 * in an island may depend on it.
 */
export function setActiveSiteContext(context) {
    activeContext = context;
}
/** The installed context, or `undefined` when none is installed. */
export function getActiveSiteContext() {
    return activeContext;
}
