/**
 * Resolves which site and which instant a featured-state check runs
 * against. Internal: not re-exported from the package entry point.
 *
 * Every resolver in the package goes through here, so there is one
 * precedence order and one failure mode:
 *
 *   1. the caller's explicit arguments, in the order given;
 *   2. the installed site context (`setActiveSiteContext`);
 *   3. for the clock only, the wall clock at the moment of this call.
 *
 * A missing site key is never defaulted. It throws.
 */
import { getActiveSiteContext, MissingSiteContextError, } from "./site-context.js";
export function resolveFeaturingScope(caller, ...candidates) {
    const all = [...candidates, getActiveSiteContext()];
    const siteKey = all.find((c) => c?.siteKey)?.siteKey;
    if (!siteKey)
        throw new MissingSiteContextError(caller);
    // Resolved once per call, so every item a builder touches in one call
    // shares an instant even when no context supplies one.
    const now = all.find((c) => c?.now)?.now ?? new Date();
    return { siteKey, now };
}
/**
 * The instant a time-dependent check should use when the caller gave
 * none: the installed context's, else the wall clock.
 */
export function resolveNow(explicit) {
    return explicit ?? getActiveSiteContext()?.now ?? new Date();
}
